import{Engine,esc,el}from'./base.js';let basePromise;
export const projectIndia=([lon,lat])=>[(lon-65)*20,(40-lat)*20];export const projectWorld=([lon,lat])=>[(lon+180)*2,(90-lat)*2];
export default class MapEngine extends Engine{constructor(h,c){super(h,c);this.mode='india';this.zoom=1;this.view=[0,0,800,760];this.seen=new Set;this.layer=0;h.innerHTML=`<div class="engineTools">${c.chapter.mapLayers?.length?`<label>${c.label("Map layer","मानचित्र परत")}<select class="mapLayer">${c.chapter.mapLayers.map((l,i)=>`<option value="${i}">${esc(c.dual(l.title.en,l.title.hi))}</option>`).join('')}</select></label>`:''}<label>${c.label('Map','मानचित्र')}<select class="mapMode"><option value="india">${c.dual('India','भारत')}</option><option value="world">${c.dual('World position','विश्व में स्थिति')}</option></select></label><label>${c.label('Zoom','ज़ूम')}<input type="range" min="1" max="4" step="0.25" value="1"><output>1×</output></label></div><svg class="studyMap" viewBox="0 0 800 760" tabindex="0" role="group" aria-label="${c.dual('Interactive India map; select a labelled feature','भारत का इंटरैक्टिव मानचित्र; नामित स्थल चुनें')}"></svg><div class="mapFeatureList"></div><p class="mapAttribution"></p><p class="mapNote"></p><div class="mapLegend"><span><i style="background:#3268a8"></i>${c.label("River","नदी")}</span><span><i style="background:#9a6335"></i>${c.label("Mountain belt","पर्वत पट्टी")}</span><span><i style="background:#f3ce76"></i>${c.label("Arrow = seasonal wind","तीर = मौसमी पवन")}</span><span>${c.label("Zones and location markers are schematic","क्षेत्र और स्थान चिह्न सांकेतिक हैं")}</span></div>`;this.svg=h.querySelector('svg');this.on(h.querySelector('.mapMode'),'change',e=>{this.mode=e.target.value;this.resetView();this.render();this.emit(this.mode==='world'?c.dual('India is highlighted in South Asia. This world view shows land, not political borders.','दक्षिण एशिया में भारत चिह्नित है। विश्व दृश्य स्थल दिखाता है, राजनीतिक सीमाएँ नहीं।'):c.text(c.chapter.goal))});this.on(h.querySelector('input'),'input',e=>this.setZoom(+e.target.value));let drag=null;this.on(this.svg,'pointerdown',e=>{drag={x:e.clientX,y:e.clientY,view:[...this.view],moved:false,feature:e.target.closest('[data-feature]')?.dataset.feature};this.svg.setPointerCapture(e.pointerId)});this.on(this.svg,'pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>6)drag.moved=true;let r=this.svg.getBoundingClientRect();this.view[0]=drag.view[0]-dx*drag.view[2]/r.width;this.view[1]=drag.view[1]-dy*drag.view[3]/r.height;this.svg.setAttribute('viewBox',this.view.join(' '))});this.on(this.svg,'pointerup',e=>{let moved=drag?.moved,id=drag?.feature;drag=null;if(!moved&&id)this.select(id)});this.on(this.svg,'pointercancel',()=>drag=null);this.on(this.svg,'wheel',e=>{e.preventDefault();this.setZoom(Math.max(1,Math.min(4,this.zoom+(e.deltaY<0?.25:-.25))))},{passive:false});this.on(this.svg,'keydown',e=>{let node=e.target.closest('[data-feature]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();this.select(node.dataset.feature);return}if(e.key==='+'||e.key==='='){e.preventDefault();this.setZoom(Math.min(4,this.zoom+.25))}else if(e.key==='-'){e.preventDefault();this.setZoom(Math.max(1,this.zoom-.25))}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();this.view[0]+=(e.key==='ArrowRight'?25:e.key==='ArrowLeft'?-25:0)/this.zoom;this.view[1]+=(e.key==='ArrowDown'?25:e.key==='ArrowUp'?-25:0)/this.zoom;this.svg.setAttribute('viewBox',this.view.join(' '))}});this.on(h.querySelector('.mapFeatureList'),'click',e=>{let b=e.target.closest('[data-feature]');if(b)this.select(b.dataset.feature)});if(h.querySelector('.mapLayer'))this.on(h.querySelector('.mapLayer'),'change',e=>{this.layer=+e.target.value;if(this.mode!=='india'){this.mode='india';h.querySelector('.mapMode').value='india';this.resetView()}this.selected=null;this.metrics.layers=(this.metrics.layers||0)+1;this.render();let layer=c.chapter.mapLayers[this.layer];this.emit(c.dual('Layer','परत')+': '+c.text(layer.title)+'. '+c.text(layer.note||layer.features[0]?.info||c.chapter.goal))});this.on(this.svg,'pointerover',e=>{let g=e.target.closest('[data-feature]');if(g){g.classList.add('hovered');let f=this.features().find(f=>f.id===g.dataset.feature);if(f)this.ctx.live(this.ctx.text(f.info))}});this.on(this.svg,'pointerout',e=>{let g=e.target.closest('[data-feature]');if(g&&!g.contains(e.relatedTarget))g.classList.remove('hovered')});this.ready=this.load()}
 features(){let layer=this.ctx.chapter.mapLayers?.[this.layer];let merged=new Map((layer?.replaceBase?[]:this.ctx.chapter.features||[]).map(f=>[f.id,f]));for(let f of layer?.features||[])merged.set(f.id,f);return [...merged.values()]}
 async load(){basePromise??=fetch('../learn/data/map-base.json').then(r=>{if(!r.ok)throw Error('Map unavailable');return r.json()});this.base=await basePromise;if(this.abort.signal.aborted)return;let c=this.ctx;this.host.querySelector('.mapAttribution').innerHTML=`© Survey of India · <a href="${esc(this.base.source.url)}" target="_blank" rel="noopener">${c.dual('Official outline','आधिकारिक रूपरेखा')}</a> · ${c.dual('Educational, non-commercial use','शैक्षिक, गैर-वाणिज्यिक उपयोग')} · <a href="${esc(this.base.source.usageNotice)}" target="_blank" rel="noopener">${c.dual('Usage notice','उपयोग की शर्तें')}</a>`;this.host.querySelector('.mapNote').textContent=c.text(this.base.note);this.render();this.emit(c.dual('Select a feature on the map or use the buttons below. Scroll to zoom; drag to pan.','मानचित्र का स्थल या नीचे का बटन चुनें। स्क्रॉल से ज़ूम करें; खींचकर खिसकाएँ।'))}
 setZoom(z){let base=this.mode==='world'?[0,0,720,360]:[0,0,800,760],cx=this.view[0]+this.view[2]/2,cy=this.view[1]+this.view[3]/2;this.zoom=z;this.view=[cx-base[2]/z/2,cy-base[3]/z/2,base[2]/z,base[3]/z];this.metrics.zoom=z;this.host.querySelector('input').value=z;this.host.querySelector('output').textContent=z+'×';this.svg.setAttribute('viewBox',this.view.join(' '));this.emit(this.ctx.dual('Zoom','ज़ूम')+': '+z+'×')}
 render(){if(!this.base)return;let c=this.ctx,data=this.mode==='india'?this.base:this.base.world,project=this.mode==='india'?projectIndia:projectWorld;this.svg.replaceChildren();let defs=el('defs'),marker=el('marker',{id:'windArrow',viewBox:'0 0 10 10',refX:8,refY:5,markerWidth:5,markerHeight:5,orient:'auto-start-reverse'});marker.append(el('path',{d:'M0 0L10 5L0 10Z',fill:'#f3ce76'}));defs.append(marker);this.svg.append(defs);let land=el('g',{fill:'#c8d6ad',stroke:'#477963','stroke-width':.5,'aria-label':c.dual('Land outline','स्थल रूपरेखा')});for(let p of data.paths)land.append(el('path',{d:p.d}));this.svg.append(land);if(this.mode==='india'){for(let lon=70;lon<=100;lon+=10)this.svg.append(el('line',{x1:projectIndia([lon,4])[0],x2:projectIndia([lon,40])[0],y1:0,y2:760,stroke:'#a6cbb933','stroke-dasharray':'3 7'}));for(let lat=10;lat<=30;lat+=10){let[x,y]=projectIndia([65,lat]);this.svg.append(el('line',{x1:0,x2:800,y1:y,y2:y,stroke:'#a6cbb933','stroke-dasharray':'3 7'}));this.svg.append(el('text',{x:8,y:y-5},lat+'°N'))}for(let f of this.features()){let g=el('g',{'data-feature':f.id,tabindex:0,role:'button',class:'mapFeature'+(this.selected===f.id?' selected':''),'aria-label':c.dual(f.title.en,f.title.hi)});if(f.points){let d=f.points.map((p,i)=>(i?'L':'M')+project(p).join(',')).join(' ')+(f.kind==='zone'?' Z':'');g.append(el('path',{d,fill:f.kind==='zone'?(f.color||'#a9c579')+'88':'none','marker-end':f.kind==='wind'?'url(#windArrow)':'',stroke:f.kind==='wind'?'#f3ce76':f.kind==='river'?'#3268a8':f.kind==='range'?'#9a6335':'#b38319','stroke-width':f.kind==='range'?13:4,'stroke-linecap':'round','stroke-dasharray':f.kind==='reference'?'8 5':''}));g.append(el('path',{d,fill:'none',stroke:'transparent','stroke-width':26}))}else{let[x,y]=project(f.location);g.append(el('circle',{cx:x,cy:y,r:f.radius||12,fill:f.color||'#c3973b',stroke:'#fff1bc','stroke-width':2}))}let pos=project(f.labelAt||f.location||f.points[Math.floor(f.points.length/2)]);if(this.labels)g.append(el('text',{x:pos[0]+9,y:pos[1]-10,class:'mapLabel'},c.dual(f.title.en,f.title.hi)));this.svg.append(g)}}else{let[x,y]=projectWorld([79,23]);let g=el('g',{'data-feature':'world-india',tabindex:0,role:'button',class:'mapFeature','aria-label':c.dual('India in South Asia','दक्षिण एशिया में भारत')});g.append(el('circle',{cx:x,cy:y,r:10,fill:'#f3c878'}));g.append(el('text',{x:x+15,y:y-5},c.dual('India','भारत')));this.svg.append(g);this.svg.append(el('text',{x:14,y:344},'Natural Earth · public domain / सार्वजनिक डोमेन'));}this.svg.setAttribute('viewBox',this.view.join(' '));this.host.querySelector('.mapFeatureList').innerHTML=(this.mode==='india'?this.features():[{id:'world-india',title:{en:'India in South Asia',hi:'दक्षिण एशिया में भारत'}}]).map(f=>`<button data-feature="${f.id}">${c.label(f.title.en,f.title.hi)}</button>`).join('')}
 select(id){let c=this.ctx,f=this.features().find(f=>f.id===id);this.selected=id;this.seen.add(id);this.metrics.visited=this.seen.size;if(f?.kind==='river')this.metrics.river=true;if(f?.kind==='range')this.metrics.range=true;this.render();this.emit(f?c.text(f.info):c.dual('India lies in South Asia, north of the equator and east of Greenwich.','भारत दक्षिण एशिया में, विषुवत वृत्त के उत्तर और ग्रीनविच के पूर्व स्थित है।'))}
 resetView(){this.zoom=1;this.view=this.mode==='world'?[0,0,720,360]:[0,0,800,760];this.host.querySelector('input').value=1;this.host.querySelector('output').textContent='1×';this.svg.setAttribute('viewBox',this.view.join(' '))}run(){this.schedule(()=>{let features=this.features();if(!features.length)return;let index=features.findIndex(f=>f.id===this.selected);this.mode='india';this.resetView();this.select(features[(index+1)%features.length].id);this.run()},4000)}}
